import{_ as e,c as d,o,ag as r}from"./chunks/framework.dvv-DFtf.js";const b=JSON.parse('{"title":"Keyboard Shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"shortcuts.md","filePath":"shortcuts.md"}'),a={name:"shortcuts.md"};function c(s,t,l,i,n,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h1><p>Complete reference of all keyboard shortcuts in Kubby.</p><h2 id="platform-differences" tabindex="-1">Platform Differences <a class="header-anchor" href="#platform-differences" aria-label="Permalink to &quot;Platform Differences&quot;">​</a></h2><p>Kubby displays shortcuts appropriate for your platform:</p><table tabindex="0"><thead><tr><th>This Guide</th><th>macOS</th><th>Windows/Linux</th></tr></thead><tbody><tr><td><code>Opt</code></td><td><code>⌥</code> (Option)</td><td><code>Alt</code></td></tr><tr><td><code>Ctrl</code></td><td><code>⌃</code> (Control)</td><td><code>Ctrl</code></td></tr><tr><td><code>Cmd</code></td><td><code>⌘</code> (Command)</td><td><code>Ctrl</code></td></tr></tbody></table><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>/</code></td><td>Filter by text</td></tr><tr><td><code>Esc</code></td><td>Clears filters</td></tr><tr><td><code>Tab</code></td><td>Move to next group</td></tr><tr><td><code>Shift+Tab</code></td><td>Move to previous group</td></tr><tr><td><code>←</code></td><td>Navigate left in group</td></tr><tr><td><code>→</code></td><td>Navigate right in group</td></tr><tr><td><code>↑</code></td><td>Select previous row item in group</td></tr><tr><td><code>↓</code></td><td>Select next row item in group</td></tr><tr><td><code>Enter</code></td><td>Open selected cluster &amp; namespace pair in last resource view (or deployments by default)</td></tr></tbody></table><h2 id="resource-list" tabindex="-1">Resource List <a class="header-anchor" href="#resource-list" aria-label="Permalink to &quot;Resource List&quot;">​</a></h2><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Opt+C</code></td><td>Change context (cluster)</td></tr><tr><td><code>Opt+N</code></td><td>Change namespace</td></tr><tr><td><code>Opt+R</code> or <code>:</code></td><td>Change resource type</td></tr><tr><td><code>Ctrl+R</code></td><td>Refresh current view</td></tr><tr><td><code>Esc</code></td><td>Go back / Cancel / Close modal</td></tr><tr><td><code>↑</code></td><td>Select previous resource</td></tr><tr><td><code>↓</code></td><td>Select next resource</td></tr><tr><td><code>Enter</code></td><td>Primary action (context-dependent)</td></tr><tr><td><code>J</code></td><td>Jump to related resources</td></tr><tr><td><code>A</code></td><td>Open AI assistant (if configured)</td></tr><tr><td><code>Esc</code></td><td>Clear filters, then return to previous view</td></tr></tbody></table><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><p>Actions are resource dependent and shown on the shortcut footer bar.</p><h2 id="hotbar" tabindex="-1">Hotbar <a class="header-anchor" href="#hotbar" aria-label="Permalink to &quot;Hotbar&quot;">​</a></h2><p>The hotbar is a toggle-able sidebar of saved screen shortcuts (resource type + context + namespace), available on all resource screens.</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Opt+H</code></td><td>Show / hide the hotbar</td></tr><tr><td><code>Opt+1</code> … <code>Opt+9</code></td><td>Jump to the first nine saved slots</td></tr></tbody></table><p>See <a href="./navigation.html#hotbar">Navigation → Hotbar</a> for adding, renaming, and removing slots. The hotbar also holds a <strong>Read-only toggle</strong> (session-only; starts from the config value) that disables mutating actions across the resource screens.</p><h2 id="log-viewer" tabindex="-1">Log Viewer <a class="header-anchor" href="#log-viewer" aria-label="Permalink to &quot;Log Viewer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>W</code></td><td>Toggle line wrap</td></tr><tr><td><code>T</code></td><td>Toggle timestamps</td></tr><tr><td><code>A</code></td><td>Toggle auto-scroll</td></tr><tr><td><code>P</code></td><td>Toggle current / previous logs</td></tr><tr><td><code>C</code></td><td>Copy logs</td></tr><tr><td><code>D</code></td><td>Open the download menu</td></tr><tr><td><code>Ctrl+R</code></td><td>Restart the log stream</td></tr><tr><td><code>Esc</code></td><td>Close the log viewer</td></tr></tbody></table><p>While the download menu (<code>D</code>) is open: <code>A</code> downloads all logs, <code>V</code> downloads the visible logs, <code>P</code> toggles including the previous terminated container, and <code>Esc</code> closes the menu.</p><h2 id="modals-dialogs" tabindex="-1">Modals &amp; Dialogs <a class="header-anchor" href="#modals-dialogs" aria-label="Permalink to &quot;Modals &amp; Dialogs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Confirm action</td></tr><tr><td><code>Esc</code></td><td>Cancel / Close</td></tr></tbody></table><h2 id="scrolling" tabindex="-1">Scrolling <a class="header-anchor" href="#scrolling" aria-label="Permalink to &quot;Scrolling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Scroll line by line</td></tr><tr><td><code>Page Up</code></td><td>Scroll up one page</td></tr><tr><td><code>Page Down</code></td><td>Scroll down one page</td></tr><tr><td><code>Home</code></td><td>Scroll to top</td></tr><tr><td><code>End</code></td><td>Scroll to bottom</td></tr></tbody></table><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Learn Incrementally</p><p>Start with <code>Enter</code>, <code>Esc</code>, <code>D</code>, and <code>L</code>. Add more shortcuts as you get comfortable.</p></div><div class="tip custom-block"><p class="custom-block-title">Action Bar Reference</p><p>The action bar at the bottom of the screen shows available shortcuts for the current view and selection.</p></div><div class="tip custom-block"><p class="custom-block-title">Modifiers</p><p>Most resource actions use single keys without modifiers. Global resource list navigation uses <code>Opt</code> (Alt) + key.</p></div>',27)])])}const p=e(a,[["render",c]]);export{b as __pageData,p as default};
